{
  "name": "@prevalentware/opencode-goal-plugin",
  "version": "0.1.99",
  "description": "OpenCode goal plugin that adds Codex-style long-running goal mode, /goal commands, persistence, and TUI status for AI coding agents.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode goal plugin",
    "opencode goal mode",
    "opencode ai",
    "goal",
    "goal-mode",
    "slash-command",
    "coding-agent",
    "ai-agent",
    "developer-tools",
    "agent",
    "tui"
  ],
  "homepage": "https://github.com/prevalentWare/opencode-goal-plugin#readme",
  "bugs": {
    "url": "https://github.com/prevalentWare/opencode-goal-plugin/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/prevalentWare/opencode-goal-plugin.git"
  },
  "license": "MIT",
  "author": "Prevalentware",
  "type": "module",
  "main": "./dist/server.js",
  "exports": {
    ".": {
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    },
    "./server": {
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    },
    "./tui": {
      "import": "./src/tui.ts",
      "default": "./src/tui.ts"
    }
  },
  "files": [
    "dist",
    "src/tui.ts",
    "src/i18n.ts",
    "src/state-path.ts",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "clean": "rm -rf dist",
    "build": "bun run clean && bun build ./src/server.ts --outdir ./dist --target bun --external @opencode-ai/plugin --external effect-goal-state --external zod",
    "ci:version": "bun scripts/resolve-ci-version.ts",
    "lint": "eslint .",
    "pack:dry-run": "npm pack --dry-run",
    "test": "bun test",
    "smoke:v2": "bun scripts/smoke-v2-lifecycle.ts",
    "test:coverage": "bun test --coverage",
    "typecheck": "bun node_modules/@typescript/native/bin/tsc --noEmit",
    "prepublishOnly": "bun run test && bun run build"
  },
  "dependencies": {
    "zod": "^4.6.7",
    "effect-goal-state": "npm:effect@^3.21.2"
  },
  "overrides": {
    "zod": "^4.6.7"
  },
  "peerDependencies": {
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "@opencode-ai/plugin": "^1.17.1",
    "@opencode/client": "2.2.5",
    "@opencode/plugin": "2.2.5",
    "@opencode/schema": "2.2.5",
    "@opencode/theme": "2.2.5",
    "@opentui/core": "0.8.2",
    "@opentui/solid": "0.8.2",
    "@types/bun": "^1.3.13",
    "@types/semver": "^7.8.0",
    "@typescript/native": "npm:typescript@^7.0.2",
    "eslint": "^10.3.0",
    "semver": "^7.8.5",
    "solid-js": "1.9.18",
    "typescript": "^6.0.3",
    "typescript-eslint": "^8.59.2"
  },
  "engines": {
    "node": "^22.13.0 || >=23.4.0",
    "opencode": ">=0.0.0-beta-0 <0.0.0 || >=1.17.1"
  },
  "publishConfig": {
    "access": "public"
  }
}
